-- Reference copy of the database schema that Entity Framework Core creates on startup.
-- The API creates these tables itself, this file exists so reviewers can read the design
-- in one place and so the double booking protection can be tried directly in psql.

-- The two tables

-- A physical table in the restaurant
CREATE TABLE dining_tables (
    "Id"       integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name"     varchar(50) NOT NULL,
    "Capacity" integer     NOT NULL
);

-- A reservation of one table for one hourly slot
CREATE TABLE bookings (
    "Id"            uuid PRIMARY KEY,
    "DiningTableId" integer      NOT NULL REFERENCES dining_tables ("Id") ON DELETE RESTRICT,
    "BookingDate"   date         NOT NULL,
    "SlotTime"      time         NOT NULL,
    "PartySize"     integer      NOT NULL,
    "CustomerName"  varchar(100) NOT NULL,
    "CustomerEmail" varchar(254) NOT NULL,
    "Status"        varchar(20)  NOT NULL,
    "CreatedAtUtc"  timestamptz  NOT NULL
);

-- The double booking protection.
-- A unique index over table + date + time means PostgreSQL itself refuses a second
-- Confirmed booking for the same slot, even when two requests arrive at the same instant.
-- The WHERE clause makes it a partial index: cancelled bookings are ignored,
-- so a cancelled slot can be booked again.
CREATE UNIQUE INDEX "IX_bookings_DiningTableId_BookingDate_SlotTime"
    ON bookings ("DiningTableId", "BookingDate", "SlotTime")
    WHERE "Status" = 'Confirmed';

-- Fake demo data
INSERT INTO dining_tables ("Id", "Name", "Capacity") VALUES
    (1, 'Window 1', 2),
    (2, 'Window 2', 2),
    (3, 'Booth 1', 4),
    (4, 'Booth 2', 4),
    (5, 'Long table', 8);
